from enum import Enum

class RecoveryLevel(Enum):
    IMMEDIATE = "immediate"   # 即座に復旧可能（再試行）
    FIXABLE = "fixable"       # 設定変更で復旧可能
    KNOWLEDGE = "knowledge"   # ナレッジベース活用
    HUMAN = "human"           # 人間の介入が必要

class AutoRecoveryManager:
    def __init__(self, sheets_manager):
        self.sheets = sheets_manager
        self.stats = {
            'total_errors': 0,
            'immediate_recoveries': 0,
            'fixable_recoveries': 0,
            'knowledge_recoveries': 0,
            'human_escalations': 0
        }

    async def handle_error(self, task_id, error, context):
        """エラーを分析して復旧を試みる"""
        error_str = str(error).lower()
        error_type = type(error).__name__

        # エラー分類
        recovery_level = self._classify_error(error_str, error_type)

        # 復旧戦略を決定
        if recovery_level == RecoveryLevel.IMMEDIATE:
            return {'action': 'retry', 'max_retries': 3}
        elif recovery_level == RecoveryLevel.FIXABLE:
            return {'action': 'apply_fix', 'fix_strategy': {...}}
        elif recovery_level == RecoveryLevel.KNOWLEDGE:
            return {'action': 'apply_knowledge', 'knowledge': {...}}
        else:
            return {'action': 'human_required', 'escalation_id': '...'}

    def _classify_error(self, error_str, error_type):
        """エラーを分類"""
        # Timeout/Network系 → IMMEDIATE
        if any(kw in error_str for kw in ['timeout', 'network', 'rate limit']):
            return RecoveryLevel.IMMEDIATE

        # 認証/設定系 → FIXABLE
        if any(kw in error_str for kw in ['auth', '401', '403', 'config']):
            return RecoveryLevel.FIXABLE

        # 既知パターン → KNOWLEDGE
        if any(kw in error_str for kw in ['invalid', 'format', 'deprecated']):
            return RecoveryLevel.KNOWLEDGE

        # その他 → HUMAN
        return RecoveryLevel.HUMAN

class TaskExecutorWithRecovery:
    def __init__(self, sheets_manager, **agents):
        self.sheets = sheets_manager
        self.recovery_manager = AutoRecoveryManager(sheets_manager)
        self.stats = {
            'total_tasks': 0,
            'successful_tasks': 0,
            'recovered_tasks': 0,
            'failed_tasks': 0
        }

    async def execute_task(self, task):
        """タスク実行（自動復旧付き）"""
        task_start = time.time()
        self.stats['total_tasks'] += 1

        # 初回実行
        result = await self._execute_single_attempt(task)

        # 成功した場合
        if result['status'] == 'success':
            self.stats['successful_tasks'] += 1
            await self._log_execution(task, result, time.time() - task_start)
            return result

        # エラーが発生 → AutoRecoveryManagerに委譲
        recovery_result = await self._attempt_recovery(task, result, task_start)

        if recovery_result['status'] == 'success':
            self.stats['recovered_tasks'] += 1
        else:
            self.stats['failed_tasks'] += 1

        return recovery_result

    async def _attempt_recovery(self, task, error_result, task_start_time):
        """AutoRecoveryManagerで復旧を試みる"""
        recovery_result = await self.recovery_manager.handle_error(
            task_id=task.get('task_id'),
            error=Exception(error_result.get('error')),
            context={'task_name': task.get('task_name')}
        )

        # 復旧レベルに応じた処理
        if recovery_result['recovery_level'] == RecoveryLevel.IMMEDIATE:
            return await self._retry_with_backoff(task, max_retries=3)
        elif recovery_result['recovery_level'] == RecoveryLevel.FIXABLE:
            modified_task = self._apply_fix_strategy(task, recovery_result['fix_strategy'])
            return await self._execute_single_attempt(modified_task)
